def get_count(self, using):
    """
    Perform a COUNT() query using the current filter constraints.
    """
    obj = self.clone()
    # Only include annotations that are referenced by ordering to
    # avoid unnecessary subqueries. Annotations that are referenced
    # by filters or other annotations have their expressions already
    # resolved and embedded in those contexts, so they can be safely
    # removed.
    order_by_refs = {
        field for field in chain(obj.order_by, obj.extra_order_by)
        if isinstance(field, str)
    }
    for alias in list(obj.annotations):
        if alias not in order_by_refs:
            del obj.annotations[alias]
    obj.add_annotation(Count("*"), alias="__count", is_summary=True)
    return obj.get_aggregation(using, ["__count"])["__count"]

def has_filters(self):
    return self.where

